fn stats(v: &Vec[Int]) -> (Int, Int, Float64) {
  if v.len() == 0 { return (0, 0, 0.0); }
  var min = v[0];
  var max = v[0];
  var sum = 0;
  var i = 0;
  while i < v.len() {
    if v[i] < min { min = v[i]; }
    if v[i] > max { max = v[i]; }
    sum = sum + v[i];
    i = i + 1;
  }
  let avg = (sum as Float64) / (v.len() as Float64);
  return (min, max, avg);
}

fn divide_rem(a: Int, b: Int) -> (Int, Int) {
  return (a / b, a % b);
}

fn main() -> Int {
  let (q, r) = divide_rem(10, 3);
  return q + r;
}
